def build_plan(scene):
    a = scene['arguments']
    p = scene['state']['public_robot_geometry']['tcp_world'][a['arm']]
    d = [a['goal'][i] - p[i][3] for i in range(3)]
    distance = sqrt(sum(x*x for x in d))
    n = max(1, min(7, int(distance/0.12)+1))
    stages = []
    for i in range(n):
        stages = stages + [{'tool': 'plan_relative_pose', 'arguments': {'arm': a['arm'], 'translation': [x/n for x in d], 'rotation_vector': [0,0,0], 'pivot_local': [0,0,0], 'steps': 4}}]
    if 'gripper_value' in a:
        steps = 12 if a['gripper_value'] < 0.8 else 6
        stages = stages + [{'tool': 'gripper', 'arguments': {'arm': a['arm'], 'value': a['gripper_value'], 'steps': steps}}]
    return {'stages': stages, 'reserve_actions': a['reserve_actions']}
